#!/usr/bin/env node
/**
 * check-registry-items-drift.mjs
 *
 * Regenerates every committed r/*.json from registry.json + its source files
 * (through build-registry-items.mjs's own buildItem/serializeItem, never a
 * second implementation) and compares the bytes with the committed file.
 *
 * Exit 1, naming the file, when:
 *   - the regenerated bytes differ from the committed file (source changed
 *     without a regeneration, or the file was hand-edited);
 *   - a committed r/*.json has no item in registry.json;
 *   - the item cannot be built at all (missing/empty source, refused import).
 * Exit 1 also when r/ holds no item: a check that compared nothing is not a pass.
 *
 * Usage: node scripts/check-registry-items-drift.mjs
 */
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { buildItem, buildPathIndex, loadRegistry, serializeItem } from "./build-registry-items.mjs";

const here = dirname(fileURLToPath(import.meta.url));

export function checkDrift({
  root = join(here, ".."),
  items = loadRegistry(),
  outDir = join(root, "r"),
} = {}) {
  const problems = [];
  const committed = existsSync(outDir)
    ? readdirSync(outDir).filter((f) => f.endsWith(".json"))
    : [];
  if (committed.length === 0) {
    problems.push(`no committed item found under ${outDir} — nothing was compared`);
    return { checked: 0, problems };
  }
  const pathToItem = buildPathIndex(items);
  for (const file of committed) {
    const name = file.slice(0, -".json".length);
    const item = items.find((i) => i.name === name);
    if (!item) {
      problems.push(`${file}: no item "${name}" in registry.json`);
      continue;
    }
    let expected;
    try {
      expected = serializeItem(buildItem(item, { root, pathToItem }));
    } catch (err) {
      problems.push(`${file}: cannot regenerate — ${err.message}`);
      continue;
    }
    if (readFileSync(join(outDir, file), "utf8") !== expected) {
      problems.push(
        `${file}: differs from its source — run \`pnpm build:registry-items ${name}\` and commit the result`,
      );
    }
  }
  return { checked: committed.length, problems };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { checked, problems } = checkDrift();
  if (problems.length > 0) {
    for (const p of problems) console.error(`check-registry-items-drift: DRIFT — ${p}`);
    process.exit(1);
  }
  console.log(`check-registry-items-drift: ${checked} committed item(s) match their source`);
}
